<?phpfunction shw_send_sms($args , $to , $bodyId) {    $sms_setting_website_set = get_option( '_shw_sms_settings_set', [] );//بدون نیاز به پکیج گیت هاب Procedural PHP نمونه کدهای	$data = array('username' =>$sms_setting_website_set['username'], 'password' => $sms_setting_website_set['password'],'text' => $args,'to' =>$to ,"bodyId"=>$bodyId);	$post_data = http_build_query($data);	$handle = curl_init('https://rest.payamak-panel.com/api/SendSMS/BaseServiceNumber');	curl_setopt($handle, CURLOPT_HTTPHEADER, array(		'content-type' => 'application/x-www-form-urlencoded'	));	curl_setopt($handle, CURLOPT_RETURNTRANSFER, true);	curl_setopt($handle, CURLOPT_SSL_VERIFYHOST, false);	curl_setopt($handle, CURLOPT_SSL_VERIFYPEER, false);	curl_setopt($handle, CURLOPT_POST, true);	curl_setopt($handle, CURLOPT_POSTFIELDS, $post_data);	$response = curl_exec($handle);	$response = json_decode($response);	return $response;//	var_dump($response);}